using System.Text;

namespace BatchRenameStudio.Core;

/// <summary>Which part of the file name the steps operate on.</summary>
public enum ApplyTo
{
    Name,
    NameAndExtension,
}

/// <summary>Processing order of the files inside the folder.</summary>
public enum SortMode
{
    Name,
    Created,
    Modified,
}

/// <summary>The kind of transformation a step performs.</summary>
public enum StepOp
{
    Replace,
    Insert,
    Remove,
    Sequence,
    Case,
    Extension,
}

/// <summary>Where a generated fragment is placed relative to the target string.</summary>
public enum Position
{
    Prefix,
    Suffix,
    Index,
}

public enum CaseMode
{
    Upper,
    Lower,
    Title,
}

public enum ExtensionMode
{
    Lower,
    Upper,
    Set,
}

/// <summary>
/// A single rule step. One mutable class carries the union of every op's fields so the
/// GUI can flip an existing row between ops without losing the user's other settings;
/// serialization only emits the fields that belong to the current <see cref="Op"/>.
/// </summary>
public sealed class RuleStep
{
    public StepOp Op { get; set; } = StepOp.Replace;

    // replace
    public string Find { get; set; } = string.Empty;
    public string ReplaceWith { get; set; } = string.Empty;
    public bool Regex { get; set; }
    public bool IgnoreCase { get; set; }

    // insert
    public string Text { get; set; } = string.Empty;
    public Position Position { get; set; } = Position.Prefix;
    public int Index { get; set; }

    // remove
    public int From { get; set; }
    public int Count { get; set; }

    // sequence
    public string Pattern { get; set; } = "{n:000}_";
    public int Start { get; set; } = 1;
    public int Step { get; set; } = 1;

    // case
    public CaseMode CaseMode { get; set; } = CaseMode.Lower;

    // extension
    public ExtensionMode ExtensionMode { get; set; } = ExtensionMode.Lower;
    public string Value { get; set; } = string.Empty;

    public RuleStep Clone() => (RuleStep)MemberwiseClone();

    /// <summary>Short one-line description used by the GUI step list.</summary>
    public string Describe()
    {
        var sb = new StringBuilder();
        switch (Op)
        {
            case StepOp.Replace:
                sb.Append("replace  \"").Append(Find).Append("\" -> \"").Append(ReplaceWith).Append('"');
                if (Regex) sb.Append("  [regex]");
                if (IgnoreCase) sb.Append("  [ignore case]");
                break;
            case StepOp.Insert:
                sb.Append("insert   \"").Append(Text).Append("\" at ").Append(Position.ToString().ToLowerInvariant());
                if (Position == Position.Index) sb.Append(' ').Append(Index);
                break;
            case StepOp.Remove:
                sb.Append("remove   ").Append(Count).Append(" char(s) from index ").Append(From);
                break;
            case StepOp.Sequence:
                sb.Append("sequence \"").Append(Pattern).Append("\" start ").Append(Start)
                  .Append(" step ").Append(Step).Append(' ').Append(Position == Position.Suffix ? "suffix" : "prefix");
                break;
            case StepOp.Case:
                sb.Append("case     ").Append(CaseMode.ToString().ToLowerInvariant());
                break;
            case StepOp.Extension:
                sb.Append("extension ").Append(ExtensionMode.ToString().ToLowerInvariant());
                if (ExtensionMode == ExtensionMode.Set) sb.Append(" \"").Append(Value).Append('"');
                break;
        }
        return sb.ToString();
    }
}

/// <summary>A complete rule set: scope, processing order and the ordered steps.</summary>
public sealed class RuleSet
{
    public ApplyTo ApplyTo { get; set; } = ApplyTo.Name;
    public SortMode Sort { get; set; } = SortMode.Name;
    public List<RuleStep> Steps { get; } = new();

    public RuleSet Clone()
    {
        var copy = new RuleSet { ApplyTo = ApplyTo, Sort = Sort };
        foreach (var s in Steps) copy.Steps.Add(s.Clone());
        return copy;
    }
}

/// <summary>Raised for malformed rule files; the message is shown to the user / stderr.</summary>
public sealed class RuleException : Exception
{
    public RuleException(string message) : base(message) { }
}

