using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>
/// Reads and writes the <c>rules.json</c> format described in the tool contract.
/// Parsing is deliberately strict about op names and enum values (a typo there silently
/// changes the whole result) and lenient about missing optional fields.
/// </summary>
public static class RuleIo
{
    public static RuleSet Load(string path)
    {
        string text;
        try
        {
            text = File.ReadAllText(path);
        }
        catch (Exception ex)
        {
            throw new RuleException($"cannot read rules file '{path}': {ex.Message}");
        }
        return Parse(text);
    }

    public static RuleSet Parse(string json)
    {
        JsonDocument doc;
        try
        {
            doc = JsonDocument.Parse(json, new JsonDocumentOptions
            {
                AllowTrailingCommas = true,
                CommentHandling = JsonCommentHandling.Skip,
            });
        }
        catch (JsonException ex)
        {
            throw new RuleException($"rules file is not valid JSON: {ex.Message}");
        }

        using (doc)
        {
            var root = doc.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
                throw new RuleException("rules file must contain a JSON object at the root.");

            var set = new RuleSet
            {
                ApplyTo = ParseEnum(GetString(root, "applyTo") ?? "name", "applyTo", new()
                {
                    ["name"] = ApplyTo.Name,
                    ["nameandextension"] = ApplyTo.NameAndExtension,
                }),
                Sort = ParseEnum(GetString(root, "sort") ?? "name", "sort", new()
                {
                    ["name"] = SortMode.Name,
                    ["created"] = SortMode.Created,
                    ["modified"] = SortMode.Modified,
                }),
            };

            if (root.TryGetProperty("steps", out var steps))
            {
                if (steps.ValueKind != JsonValueKind.Array)
                    throw new RuleException("'steps' must be an array.");
                var i = 0;
                foreach (var e in steps.EnumerateArray())
                {
                    set.Steps.Add(ParseStep(e, i));
                    i++;
                }
            }

            return set;
        }
    }

    private static RuleStep ParseStep(JsonElement e, int index)
    {
        if (e.ValueKind != JsonValueKind.Object)
            throw new RuleException($"steps[{index}] must be an object.");

        var opText = GetString(e, "op") ?? throw new RuleException($"steps[{index}] is missing 'op'.");
        var step = new RuleStep
        {
            Op = ParseEnum(opText, $"steps[{index}].op", new()
            {
                ["replace"] = StepOp.Replace,
                ["insert"] = StepOp.Insert,
                ["remove"] = StepOp.Remove,
                ["sequence"] = StepOp.Sequence,
                ["case"] = StepOp.Case,
                ["extension"] = StepOp.Extension,
            }),
        };

        switch (step.Op)
        {
            case StepOp.Replace:
                step.Find = GetString(e, "find") ?? string.Empty;
                step.ReplaceWith = GetString(e, "replaceWith") ?? string.Empty;
                step.Regex = GetBool(e, "regex", false);
                step.IgnoreCase = GetBool(e, "ignoreCase", false);
                if (step.Regex)
                {
                    try
                    {
                        _ = new Regex(step.Find, step.IgnoreCase ? RegexOptions.IgnoreCase : RegexOptions.None);
                    }
                    catch (ArgumentException ex)
                    {
                        throw new RuleException($"steps[{index}] has an invalid regex: {ex.Message}");
                    }
                }
                break;

            case StepOp.Insert:
                step.Text = GetString(e, "text") ?? string.Empty;
                step.Position = ParsePosition(GetString(e, "position") ?? "prefix", $"steps[{index}].position", allowIndex: true);
                step.Index = GetInt(e, "index", 0);
                break;

            case StepOp.Remove:
                step.From = GetInt(e, "from", 0);
                step.Count = GetInt(e, "count", 0);
                break;

            case StepOp.Sequence:
                step.Pattern = GetString(e, "pattern") ?? "{n:000}";
                step.Start = GetInt(e, "start", 1);
                step.Step = GetInt(e, "step", 1);
                step.Position = ParsePosition(GetString(e, "position") ?? "prefix", $"steps[{index}].position", allowIndex: false);
                break;

            case StepOp.Case:
                step.CaseMode = ParseEnum(GetString(e, "mode") ?? "lower", $"steps[{index}].mode", new()
                {
                    ["upper"] = CaseMode.Upper,
                    ["lower"] = CaseMode.Lower,
                    ["title"] = CaseMode.Title,
                });
                break;

            case StepOp.Extension:
                step.ExtensionMode = ParseEnum(GetString(e, "mode") ?? "lower", $"steps[{index}].mode", new()
                {
                    ["lower"] = ExtensionMode.Lower,
                    ["upper"] = ExtensionMode.Upper,
                    ["set"] = ExtensionMode.Set,
                });
                step.Value = GetString(e, "value") ?? string.Empty;
                break;
        }

        return step;
    }

    private static Position ParsePosition(string raw, string field, bool allowIndex)
    {
        var map = new Dictionary<string, Position>
        {
            ["prefix"] = Position.Prefix,
            ["suffix"] = Position.Suffix,
        };
        if (allowIndex) map["index"] = Position.Index;
        return ParseEnum(raw, field, map);
    }

    private static T ParseEnum<T>(string raw, string field, Dictionary<string, T> map)
    {
        if (map.TryGetValue(raw.Trim().ToLowerInvariant(), out var v)) return v;
        throw new RuleException($"'{field}' has unsupported value '{raw}'. Expected one of: {string.Join(", ", map.Keys)}.");
    }

    private static string? GetString(JsonElement obj, string name)
    {
        foreach (var p in obj.EnumerateObject())
        {
            if (!string.Equals(p.Name, name, StringComparison.OrdinalIgnoreCase)) continue;
            return p.Value.ValueKind switch
            {
                JsonValueKind.String => p.Value.GetString(),
                JsonValueKind.Null => null,
                _ => p.Value.ToString(),
            };
        }
        return null;
    }

    private static bool GetBool(JsonElement obj, string name, bool fallback)
    {
        foreach (var p in obj.EnumerateObject())
        {
            if (!string.Equals(p.Name, name, StringComparison.OrdinalIgnoreCase)) continue;
            return p.Value.ValueKind switch
            {
                JsonValueKind.True => true,
                JsonValueKind.False => false,
                JsonValueKind.String => bool.TryParse(p.Value.GetString(), out var b) && b,
                _ => fallback,
            };
        }
        return fallback;
    }

    private static int GetInt(JsonElement obj, string name, int fallback)
    {
        foreach (var p in obj.EnumerateObject())
        {
            if (!string.Equals(p.Name, name, StringComparison.OrdinalIgnoreCase)) continue;
            if (p.Value.ValueKind == JsonValueKind.Number && p.Value.TryGetInt32(out var n)) return n;
            if (p.Value.ValueKind == JsonValueKind.String && int.TryParse(p.Value.GetString(), out var s)) return s;
            return fallback;
        }
        return fallback;
    }

    /// <summary>Serializes a rule set back to the contract's rules.json shape.</summary>
    public static string Serialize(RuleSet set)
    {
        var buffer = new MemoryStream();
        using (var w = new Utf8JsonWriter(buffer, new JsonWriterOptions
        {
            Indented = true,
            Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
        }))
        {
            w.WriteStartObject();
            w.WriteString("applyTo", set.ApplyTo == ApplyTo.Name ? "name" : "nameAndExtension");
            w.WriteString("sort", set.Sort.ToString().ToLowerInvariant());
            w.WriteStartArray("steps");
            foreach (var s in set.Steps)
            {
                w.WriteStartObject();
                switch (s.Op)
                {
                    case StepOp.Replace:
                        w.WriteString("op", "replace");
                        w.WriteString("find", s.Find);
                        w.WriteString("replaceWith", s.ReplaceWith);
                        w.WriteBoolean("regex", s.Regex);
                        w.WriteBoolean("ignoreCase", s.IgnoreCase);
                        break;
                    case StepOp.Insert:
                        w.WriteString("op", "insert");
                        w.WriteString("text", s.Text);
                        w.WriteString("position", s.Position.ToString().ToLowerInvariant());
                        w.WriteNumber("index", s.Index);
                        break;
                    case StepOp.Remove:
                        w.WriteString("op", "remove");
                        w.WriteNumber("from", s.From);
                        w.WriteNumber("count", s.Count);
                        break;
                    case StepOp.Sequence:
                        w.WriteString("op", "sequence");
                        w.WriteString("pattern", s.Pattern);
                        w.WriteNumber("start", s.Start);
                        w.WriteNumber("step", s.Step);
                        w.WriteString("position", s.Position == Position.Suffix ? "suffix" : "prefix");
                        break;
                    case StepOp.Case:
                        w.WriteString("op", "case");
                        w.WriteString("mode", s.CaseMode.ToString().ToLowerInvariant());
                        break;
                    case StepOp.Extension:
                        w.WriteString("op", "extension");
                        w.WriteString("mode", s.ExtensionMode.ToString().ToLowerInvariant());
                        if (s.ExtensionMode == ExtensionMode.Set) w.WriteString("value", s.Value);
                        break;
                }
                w.WriteEndObject();
            }
            w.WriteEndArray();
            w.WriteEndObject();
        }
        return Encoding.UTF8.GetString(buffer.ToArray()).Replace("\r\n", "\n");
    }

    public static void Save(RuleSet set, string path)
    {
        File.WriteAllText(path, Serialize(set), new UTF8Encoding(false));
    }
}

