using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;

namespace BatchRenameStudio.Core;

public static class PlanStatus
{
    public const string Ok = "ok";
    public const string Collision = "collision";
    public const string Unchanged = "unchanged";
    public const string Invalid = "invalid";
}

/// <summary>One row of the plan: what a file is called now and what it would be called.</summary>
public sealed class PlanItem
{
    public required string Original { get; init; }
    public required string Proposed { get; init; }
    public required string Status { get; set; }
    public string Reason { get; set; } = string.Empty;
}

public sealed class PlanSummary
{
    public int Total { get; set; }
    public int Ok { get; set; }
    public int Collision { get; set; }
    public int Unchanged { get; set; }
    public int Invalid { get; set; }
}

/// <summary>The full plan for one folder + rule set.</summary>
public sealed class RenamePlan
{
    public const int CurrentSchemaVersion = 1;

    public int SchemaVersion { get; init; } = CurrentSchemaVersion;
    public List<PlanItem> Items { get; } = new();
    public PlanSummary Summary { get; } = new();

    public void RecomputeSummary()
    {
        Summary.Total = Items.Count;
        Summary.Ok = Items.Count(i => i.Status == PlanStatus.Ok);
        Summary.Collision = Items.Count(i => i.Status == PlanStatus.Collision);
        Summary.Unchanged = Items.Count(i => i.Status == PlanStatus.Unchanged);
        Summary.Invalid = Items.Count(i => i.Status == PlanStatus.Invalid);
    }

    /// <summary>
    /// Serializes the plan. Newlines are normalized to LF and the encoder is fixed so that
    /// identical inputs always produce a byte-identical document (contract rule 15).
    /// </summary>
    public string ToJson()
    {
        var buffer = new MemoryStream();
        using (var w = new Utf8JsonWriter(buffer, new JsonWriterOptions
        {
            Indented = true,
            Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
        }))
        {
            w.WriteStartObject();
            w.WriteNumber("schemaVersion", SchemaVersion);
            w.WriteStartArray("items");
            foreach (var item in Items)
            {
                w.WriteStartObject();
                w.WriteString("original", item.Original);
                w.WriteString("proposed", item.Proposed);
                w.WriteString("status", item.Status);
                w.WriteString("reason", item.Reason ?? string.Empty);
                w.WriteEndObject();
            }
            w.WriteEndArray();
            w.WriteStartObject("summary");
            w.WriteNumber("total", Summary.Total);
            w.WriteNumber("ok", Summary.Ok);
            w.WriteNumber("collision", Summary.Collision);
            w.WriteNumber("unchanged", Summary.Unchanged);
            w.WriteNumber("invalid", Summary.Invalid);
            w.WriteEndObject();
            w.WriteEndObject();
        }
        return Encoding.UTF8.GetString(buffer.ToArray()).Replace("\r\n", "\n") + "\n";
    }

    /// <summary>Writes the plan as UTF-8 without a byte order mark.</summary>
    public void WriteTo(string path)
    {
        var full = Path.GetFullPath(path);
        var dir = Path.GetDirectoryName(full);
        if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
        File.WriteAllText(full, ToJson(), new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
    }

    public string SummaryLine() =>
        $"total={Summary.Total} ok={Summary.Ok} collision={Summary.Collision} " +
        $"unchanged={Summary.Unchanged} invalid={Summary.Invalid}";
}

