using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>A file as the engine sees it — decoupled from the filesystem so the rules are testable.</summary>
public sealed record FileEntry(string Name, DateTime CreatedUtc, DateTime ModifiedUtc);

/// <summary>
/// Pure implementation of the rename semantics in the tool contract.
/// Nothing here touches the filesystem except <see cref="Scan"/>.
/// </summary>
public static class RenameEngine
{
    private static readonly char[] IllegalChars = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    private static readonly HashSet<string> ReservedNames = new(StringComparer.OrdinalIgnoreCase)
    {
        "CON", "PRN", "AUX", "NUL",
        "COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8", "COM9",
        "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9",
    };

    private static readonly Regex SequenceToken = new(@"\{n:(0+)\}", RegexOptions.Compiled | RegexOptions.CultureInvariant);

    /// <summary>Rule 1: regular files directly inside the folder, non-recursive, no directories.</summary>
    public static List<FileEntry> Scan(string directory)
    {
        var info = new DirectoryInfo(directory);
        if (!info.Exists) throw new DirectoryNotFoundException($"folder not found: {directory}");

        var result = new List<FileEntry>();
        foreach (var f in info.GetFiles())
        {
            if ((f.Attributes & FileAttributes.Directory) != 0) continue;
            result.Add(new FileEntry(f.Name, f.CreationTimeUtc, f.LastWriteTimeUtc));
        }
        return result;
    }

    /// <summary>Rule 5 / 14: processing order. Ties break on ordinal name so the plan is deterministic.</summary>
    public static List<FileEntry> SortEntries(IEnumerable<FileEntry> entries, SortMode sort) => sort switch
    {
        SortMode.Created => entries.OrderBy(e => e.CreatedUtc).ThenBy(e => e.Name, StringComparer.Ordinal).ToList(),
        SortMode.Modified => entries.OrderBy(e => e.ModifiedUtc).ThenBy(e => e.Name, StringComparer.Ordinal).ToList(),
        _ => entries.OrderBy(e => e.Name, StringComparer.Ordinal).ToList(),
    };

    public static RenamePlan BuildPlan(string directory, RuleSet rules) => BuildPlan(Scan(directory), rules);

    public static RenamePlan BuildPlan(IEnumerable<FileEntry> entries, RuleSet rules)
    {
        var ordered = SortEntries(entries, rules.Sort);

        var proposed = new string[ordered.Count];
        for (var i = 0; i < ordered.Count; i++)
            proposed[i] = Propose(ordered[i].Name, rules, i);

        // Rule 13: collision look-ups are case-insensitive, both against the other files that
        // already exist and against the other proposed names.
        var originals = new HashSet<string>(ordered.Select(e => e.Name), StringComparer.OrdinalIgnoreCase);
        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var p in proposed)
            proposedCounts[p] = proposedCounts.TryGetValue(p, out var c) ? c + 1 : 1;

        var plan = new RenamePlan();
        for (var i = 0; i < ordered.Count; i++)
        {
            var original = ordered[i].Name;
            var name = proposed[i];
            string status, reason;

            if (TryInvalidReason(name, out var invalidReason))
            {
                status = PlanStatus.Invalid;
                reason = invalidReason;
            }
            else if (proposedCounts[name] > 1)
            {
                status = PlanStatus.Collision;
                reason = "another file in this batch proposes the same name";
            }
            else if (originals.Contains(name) && !string.Equals(name, original, StringComparison.OrdinalIgnoreCase))
            {
                status = PlanStatus.Collision;
                reason = "a different existing file already has this name";
            }
            else if (string.Equals(name, original, StringComparison.Ordinal))
            {
                status = PlanStatus.Unchanged;
                reason = string.Empty;
            }
            else
            {
                status = PlanStatus.Ok;
                reason = string.Empty;
            }

            plan.Items.Add(new PlanItem
            {
                Original = original,
                Proposed = name,
                Status = status,
                Reason = reason,
            });
        }

        plan.RecomputeSummary();
        return plan;
    }

    /// <summary>Rule 2: split on the LAST dot; an extension never includes the dot.</summary>
    public static void SplitName(string name, out string basePart, out string extPart)
    {
        var dot = name.LastIndexOf('.');
        if (dot > 0)
        {
            basePart = name[..dot];
            extPart = name[(dot + 1)..];
        }
        else
        {
            basePart = name;
            extPart = string.Empty;
        }
    }

    /// <summary>Rule 12: base + "." + ext, or just base when there is no extension.</summary>
    public static string JoinName(string basePart, string extPart) =>
        extPart.Length == 0 ? basePart : basePart + "." + extPart;

    /// <summary>Runs every step, in order, over one file name. <paramref name="index"/> is the 0-based processing position.</summary>
    public static string Propose(string name, RuleSet rules, int index)
    {
        if (rules.ApplyTo == ApplyTo.NameAndExtension)
        {
            // Rule 3/12: the target string is the whole file name; an 'extension' step
            // re-splits whatever the string currently looks like.
            var target = name;
            foreach (var step in rules.Steps)
            {
                if (step.Op == StepOp.Extension)
                {
                    SplitName(target, out var b, out var e);
                    target = JoinName(b, ApplyExtension(e, step));
                }
                else
                {
                    target = ApplyStep(target, step, index);
                }
            }
            return target;
        }

        // applyTo == "name": steps run on the base, 'extension' steps run on the extension.
        SplitName(name, out var basePart, out var extPart);
        foreach (var step in rules.Steps)
        {
            if (step.Op == StepOp.Extension) extPart = ApplyExtension(extPart, step);
            else basePart = ApplyStep(basePart, step, index);
        }
        return JoinName(basePart, extPart);
    }

    private static string ApplyStep(string target, RuleStep step, int index) => step.Op switch
    {
        StepOp.Replace => ApplyReplace(target, step),
        StepOp.Insert => ApplyInsert(target, step),
        StepOp.Remove => ApplyRemove(target, step),
        StepOp.Sequence => ApplySequence(target, step, index),
        StepOp.Case => ApplyCase(target, step.CaseMode),
        _ => target,
    };

    /// <summary>Rule 6.</summary>
    private static string ApplyReplace(string target, RuleStep step)
    {
        if (step.Regex)
        {
            var options = RegexOptions.CultureInvariant;
            if (step.IgnoreCase) options |= RegexOptions.IgnoreCase;
            try
            {
                return Regex.Replace(target, step.Find, step.ReplaceWith, options);
            }
            catch (ArgumentException)
            {
                return target; // rules are validated on load; be inert rather than crash here
            }
        }

        if (step.Find.Length == 0) return target; // nothing to find: no-op
        return target.Replace(step.Find, step.ReplaceWith,
            step.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);
    }

    /// <summary>Rule 7.</summary>
    private static string ApplyInsert(string target, RuleStep step) => step.Position switch
    {
        Position.Prefix => step.Text + target,
        Position.Suffix => target + step.Text,
        _ => target.Insert(Math.Clamp(step.Index, 0, target.Length), step.Text),
    };

    /// <summary>Rule 8.</summary>
    private static string ApplyRemove(string target, RuleStep step)
    {
        var from = Math.Clamp(step.From, 0, target.Length);
        var count = Math.Clamp(step.Count, 0, target.Length - from);
        return count == 0 ? target : target.Remove(from, count);
    }

    /// <summary>Rule 9. The counter advances for every file, whatever that file's final status is.</summary>
    private static string ApplySequence(string target, RuleStep step, int index)
    {
        var counter = (long)step.Start + (long)step.Step * index;
        var rendered = RenderSequence(step.Pattern, counter);
        return step.Position == Position.Suffix ? target + rendered : rendered + target;
    }

    public static string RenderSequence(string pattern, long counter) =>
        SequenceToken.Replace(pattern, m => counter.ToString(new string('0', m.Groups[1].Value.Length)));

    /// <summary>Rule 10.</summary>
    public static string ApplyCase(string target, CaseMode mode)
    {
        switch (mode)
        {
            case CaseMode.Upper: return target.ToUpperInvariant();
            case CaseMode.Lower: return target.ToLowerInvariant();
            default:
                var chars = target.ToCharArray();
                var inRun = false;
                for (var i = 0; i < chars.Length; i++)
                {
                    if (char.IsLetter(chars[i]))
                    {
                        chars[i] = inRun ? char.ToLowerInvariant(chars[i]) : char.ToUpperInvariant(chars[i]);
                        inRun = true;
                    }
                    else
                    {
                        inRun = false;
                    }
                }
                return new string(chars);
        }
    }

    /// <summary>Rule 11.</summary>
    private static string ApplyExtension(string extPart, RuleStep step) => step.ExtensionMode switch
    {
        ExtensionMode.Upper => extPart.ToUpperInvariant(),
        ExtensionMode.Lower => extPart.ToLowerInvariant(),
        _ => step.Value,
    };

    /// <summary>Rule 13, first bullet.</summary>
    public static bool TryInvalidReason(string proposed, out string reason)
    {
        if (proposed.Length == 0)
        {
            reason = "proposed name is empty";
            return true;
        }
        if (proposed.Length > 255)
        {
            reason = "proposed name is longer than 255 characters";
            return true;
        }
        foreach (var c in proposed)
        {
            if (c < ' ')
            {
                reason = "proposed name contains a control character";
                return true;
            }
            if (Array.IndexOf(IllegalChars, c) >= 0)
            {
                reason = $"proposed name contains the illegal character '{c}'";
                return true;
            }
        }
        SplitName(proposed, out var basePart, out _);
        if (ReservedNames.Contains(basePart))
        {
            reason = $"'{basePart}' is a reserved Windows device name";
            return true;
        }
        reason = string.Empty;
        return false;
    }

    /// <summary>Human-readable preview of what a single step does, used by the GUI tooltip.</summary>
    public static string DescribeRules(RuleSet rules)
    {
        var sb = new StringBuilder();
        sb.Append("applyTo=").Append(rules.ApplyTo == ApplyTo.Name ? "name" : "nameAndExtension");
        sb.Append(", sort=").Append(rules.Sort.ToString().ToLowerInvariant());
        sb.Append(", steps=").Append(rules.Steps.Count);
        return sb.ToString();
    }
}

