    }

    /// <summary>Rule 7.</summary>
    private static string ApplyInsert(string target, RuleStep step) => step.Position switch
    {
        Position.Prefix => step.Text + target,
        Position.Suffix => target + step.Text,
        _ => target.Insert(Math.Clamp(step.Index, 0, target.Length), step.Text),
    };

    /// <summary>Rule 8.</summary>
    private static string ApplyRemove(string target, RuleStep step)
    {
        var from = Math.Clamp(step.From, 0, target.Length);
        var count = Math.Clamp(step.Count, 0, target.Length - from);
        return count == 0 ? target : target.Remove(from, count);
    }

    /// <summary>Rule 9. The counter advances for every file, whatever that file's final status is.</summary>
    private static string ApplySequence(string target, RuleStep step, int index)
    {
        var counter = (long)step.Start + (long)step.Step * index;
        var rendered = RenderSequence(step.Pattern, counter);
        return step.Position == Position.Suffix ? target + rendered : rendered + target;
    }

    public static string RenderSequence(string pattern, long counter) =>
        SequenceToken.Replace(pattern, m => counter.ToString(new string('0', m.Groups[1].Value.Length)));

    /// <summary>Rule 10.</summary>
    public static string ApplyCase(string target, CaseMode mode)
    {
        switch (mode)
        {
            case CaseMode.Upper: return target.ToUpperInvariant();
            case CaseMode.Lower: return target.ToLowerInvariant();
            default:
                var chars = target.ToCharArray();
                var inRun = false;
                for (var i = 0; i < chars.Length; i++)
                {
                    if (char.IsLetter(chars[i]))
                    {
                        chars[i] = inRun ? char.ToLowerInvariant(chars[i]) : char.ToUpperInvariant(chars[i]);
                        inRun = true;
                    }
                    else
                    {
                        inRun = false;
                    }
                }
                return new string(chars);
        }
    }

    /// <summary>Rule 11.</summary>
    private static string ApplyExtension(string extPart, RuleStep step) => step.ExtensionMode switch
    {
        ExtensionMode.Upper => extPart.ToUpperInvariant(),
        ExtensionMode.Lower => extPart.ToLowerInvariant(),
        _ => step.Value,
    };

    /// <summary>Rule 13, first bullet.</summary>
    public static bool TryInvalidReason(string proposed, out string reason)
    {
        if (proposed.Length == 0)
        {
            reason = "proposed name is empty";
            return true;
        }
        if (proposed.Length > 255)
        {
            reason = "proposed name is longer than 255 characters";
            return true;
        }
        foreach (var c in proposed)
        {
            if (c < ' ')
            {
                reason = "proposed name contains a control character";
                return true;
            }
            if (Array.IndexOf(IllegalChars, c) >= 0)
            {
                reason = $"proposed name contains the illegal character '{c}'";
                return true;
            }
        }
        SplitName(proposed, out var basePart, out _);
        if (ReservedNames.Contains(basePart))
        {
            reason = $"'{basePart}' is a reserved Windows device name";
            return true;
        }
        reason = string.Empty;
        return false;
    }

    /// <summary>Human-readable preview of what a single step does, used by the GUI tooltip.</summary>
    public static string DescribeRules(RuleSet rules)
    {
        var sb = new StringBuilder();
        sb.Append("applyTo=").Append(rules.ApplyTo == ApplyTo.Name ? "name" : "nameAndExtension");
        sb.Append(", sort=").Append(rules.Sort.ToString().ToLowerInvariant());
        sb.Append(", steps=").Append(rules.Steps.Count);
        return sb.ToString();
    }
}

