namespace BatchRenameStudio.Core;

/// <summary>One completed rename, kept so it can be reversed.</summary>
public sealed record RenameRecord(string From, string To);

/// <summary>A whole applied batch — the unit of undo.</summary>
public sealed class RenameBatch
{
    public required string Directory { get; init; }
    public required DateTime AppliedAt { get; init; }
    public List<RenameRecord> Records { get; } = new();
    public List<string> Errors { get; } = new();

    public string Describe() =>
        $"{AppliedAt:HH:mm:ss}  {Records.Count} file(s) in {System.IO.Path.GetFileName(Directory.TrimEnd('\\'))}";
}

/// <summary>
/// Applies a plan to disk. Renames go through unique temporary names first, so that
/// cycles and swaps (a -> b, b -> a) work rather than failing halfway.
/// </summary>
public static class RenameExecutor
{
    public static RenameBatch Apply(string directory, IEnumerable<PlanItem> items, DateTime nowUtc)
    {
        var batch = new RenameBatch { Directory = directory, AppliedAt = nowUtc.ToLocalTime() };
        var targets = items.Where(i => i.Status == PlanStatus.Ok).ToList();
        if (targets.Count == 0) return batch;

        var staged = new List<(string Temp, string Final, string Original)>();
        var token = "brs-" + Guid.NewGuid().ToString("N")[..8];

        // Phase 1: move every source out of the way.
        for (var i = 0; i < targets.Count; i++)
        {
            var from = Path.Combine(directory, targets[i].Original);
            var temp = Path.Combine(directory, $"{token}-{i}.tmp");
            try
            {
                File.Move(from, temp);
                staged.Add((temp, Path.Combine(directory, targets[i].Proposed), targets[i].Original));
            }
            catch (Exception ex)
            {
                batch.Errors.Add($"{targets[i].Original}: {ex.Message}");
            }
        }

        // Phase 2: move each temporary file to its final name.
        foreach (var (temp, final, original) in staged)
        {
            try
            {
                File.Move(temp, final);
                batch.Records.Add(new RenameRecord(original, Path.GetFileName(final)));
            }
            catch (Exception ex)
            {
                batch.Errors.Add($"{original}: {ex.Message}");
                try
                {
                    File.Move(temp, Path.Combine(directory, original)); // put it back
                }
                catch (Exception restoreEx)
                {
                    batch.Errors.Add($"{original}: could not be restored from {Path.GetFileName(temp)} ({restoreEx.Message})");
                }
            }
        }

        return batch;
    }

    /// <summary>Reverses a batch, newest record first, using the same two-phase move.</summary>
    public static List<string> Undo(RenameBatch batch)
    {
        var errors = new List<string>();
        var token = "brs-undo-" + Guid.NewGuid().ToString("N")[..8];
        var staged = new List<(string Temp, string Final, string Current)>();
        var records = Enumerable.Reverse(batch.Records).ToList();

        for (var i = 0; i < records.Count; i++)
        {
            var current = Path.Combine(batch.Directory, records[i].To);
            var temp = Path.Combine(batch.Directory, $"{token}-{i}.tmp");
            try
            {
                File.Move(current, temp);
                staged.Add((temp, Path.Combine(batch.Directory, records[i].From), records[i].To));
            }
            catch (Exception ex)
            {
                errors.Add($"{records[i].To}: {ex.Message}");
            }
        }

        foreach (var (temp, final, current) in staged)
        {
            try
            {
                File.Move(temp, final);
            }
            catch (Exception ex)
            {
                errors.Add($"{current}: {ex.Message}");
                try { File.Move(temp, Path.Combine(batch.Directory, current)); }
                catch (Exception restoreEx) { errors.Add($"{current}: could not be restored ({restoreEx.Message})"); }
            }
        }

        return errors;
    }
}

