using System.Runtime.InteropServices;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The executable is a Windows subsystem (GUI) binary, so it has no console of its own.
/// When stdout is already redirected by the caller we leave it strictly alone — that is the
/// case the headless contract is verified in. Only when there is no stdout handle at all do
/// we borrow the parent console, so a human running the command in cmd still sees the summary.
/// </summary>
internal static class ConsoleBridge
{
    private const int StdOutputHandle = -11;
    private const int AttachParentProcess = -1;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int nStdHandle);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(int dwProcessId);

    public static void EnsureAttached()
    {
        try
        {
            var handle = GetStdHandle(StdOutputHandle);
            if (handle != IntPtr.Zero && handle != new IntPtr(-1)) return; // already redirected or inherited

            if (!AttachConsole(AttachParentProcess)) return;

            var stdout = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = true };
            Console.SetOut(stdout);
            var stderr = new StreamWriter(Console.OpenStandardError()) { AutoFlush = true };
            Console.SetError(stderr);
        }
        catch
        {
            // No console is not an error: the plan file is the real output.
        }
    }
}

