using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Headless planning mode:
///   BatchRenameStudio.exe --plan --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;plan.json&gt;
/// Exit 0 on success, one summary line on stdout, nothing renamed.
/// </summary>
internal static class PlanCommand
{
    public const int ExitOk = 0;
    public const int ExitUsage = 2;
    public const int ExitFailed = 3;

    public static int Run(string[] args)
    {
        ConsoleBridge.EnsureAttached();

        string? dir = null, rulesPath = null, outPath = null;

        for (var i = 0; i < args.Length; i++)
        {
            var a = args[i];
            switch (a.ToLowerInvariant())
            {
                case "--plan":
                    break;
                case "--dir":
                    if (!TryTake(args, ref i, out dir)) return Usage("--dir requires a value");
                    break;
                case "--rules":
                    if (!TryTake(args, ref i, out rulesPath)) return Usage("--rules requires a value");
                    break;
                case "--out":
                    if (!TryTake(args, ref i, out outPath)) return Usage("--out requires a value");
                    break;
                default:
                    return Usage($"unknown argument '{a}'");
            }
        }

        if (string.IsNullOrWhiteSpace(dir)) return Usage("--dir is required");
        if (string.IsNullOrWhiteSpace(rulesPath)) return Usage("--rules is required");
        if (string.IsNullOrWhiteSpace(outPath)) return Usage("--out is required");

        try
        {
            if (!Directory.Exists(dir))
            {
                Console.Error.WriteLine($"error: folder not found: {dir}");
                return ExitFailed;
            }
            if (!File.Exists(rulesPath))
            {
                Console.Error.WriteLine($"error: rules file not found: {rulesPath}");
                return ExitFailed;
            }

            var rules = RuleIo.Load(rulesPath);
            var plan = RenameEngine.BuildPlan(dir, rules);
            plan.WriteTo(outPath);

            Console.Out.WriteLine(plan.SummaryLine());
            Console.Out.Flush();
            return ExitOk;
        }
        catch (RuleException ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return ExitFailed;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return ExitFailed;
        }
    }

    private static bool TryTake(string[] args, ref int i, out string? value)
    {
        if (i + 1 >= args.Length)
        {
            value = null;
            return false;
        }
        value = args[++i];
        return true;
    }

    private static int Usage(string problem)
    {
        Console.Error.WriteLine($"error: {problem}");
        Console.Error.WriteLine("usage: BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>");
        return ExitUsage;
    }
}

