using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// Property sheet for the currently selected rule step. The rows are rebuilt whenever the
/// bound step (or its op) changes, so only the fields that actually mean something are shown.
/// </summary>
internal sealed class StepEditor : Panel
{
    private readonly TableLayoutPanel _table;
    private RuleStep? _step;
    private bool _suspend;

    /// <summary>Raised when the user edits any field. The bound step has already been updated.</summary>
    public event EventHandler? Changed;

    public StepEditor()
    {
        Padding = new Padding(8);
        _table = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 2,
            AutoScroll = true,
            GrowStyle = TableLayoutPanelGrowStyle.AddRows,
        };
        _table.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 118));
        _table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        Controls.Add(_table);
    }

    public void Bind(RuleStep? step)
    {
        _step = step;
        Rebuild();
    }

    private void Rebuild()
    {
        _suspend = true;
        _table.SuspendLayout();
        foreach (Control c in _table.Controls) c.Dispose();
        _table.Controls.Clear();
        _table.RowStyles.Clear();
        _table.RowCount = 0;

        if (_step is null)
        {
            AddRow(string.Empty, new Label
            {
                Text = "Select a step on the left, or add one with the + button.",
                AutoSize = true,
                ForeColor = SystemColors.GrayText,
            });
            _table.ResumeLayout();
            _suspend = false;
            return;
        }

        var opBox = Combo(new[] { "replace", "insert", "remove", "sequence", "case", "extension" },
            _step.Op.ToString().ToLowerInvariant());
        opBox.SelectedIndexChanged += (_, _) =>
        {
            if (_suspend || _step is null) return;
            _step.Op = opBox.SelectedItem!.ToString() switch
            {
                "insert" => StepOp.Insert,
                "remove" => StepOp.Remove,
                "sequence" => StepOp.Sequence,
                "case" => StepOp.Case,
                "extension" => StepOp.Extension,
                _ => StepOp.Replace,
            };
            if (_step.Op == StepOp.Sequence && _step.Position == Position.Index) _step.Position = Position.Prefix;
            Rebuild();
            OnChanged();
        };
        AddRow("Operation", opBox);

        switch (_step.Op)
        {
            case StepOp.Replace:
                AddRow("Find", Text(_step.Find, v => _step!.Find = v));
                AddRow("Replace with", Text(_step.ReplaceWith, v => _step!.ReplaceWith = v));
                AddRow(string.Empty, Check("Regular expression ($1 back-references allowed)", _step.Regex, v => _step!.Regex = v));
                AddRow(string.Empty, Check("Ignore case", _step.IgnoreCase, v => _step!.IgnoreCase = v));
                break;

            case StepOp.Insert:
                AddRow("Text", Text(_step.Text, v => _step!.Text = v));
                var insertPos = Combo(new[] { "prefix", "suffix", "index" }, _step.Position.ToString().ToLowerInvariant());
                insertPos.SelectedIndexChanged += (_, _) =>
                {
                    if (_suspend || _step is null) return;
                    _step.Position = insertPos.SelectedItem!.ToString() switch
                    {
                        "suffix" => Position.Suffix,
                        "index" => Position.Index,
                        _ => Position.Prefix,
                    };
                    Rebuild();
                    OnChanged();
                };
                AddRow("Position", insertPos);
                if (_step.Position == Position.Index)
                    AddRow("Index", Number(_step.Index, v => _step!.Index = v));
                break;

            case StepOp.Remove:
                AddRow("From index", Number(_step.From, v => _step!.From = v));
                AddRow("Count", Number(_step.Count, v => _step!.Count = v));
                break;

            case StepOp.Sequence:
                AddRow("Pattern", Text(_step.Pattern, v => _step!.Pattern = v));
                AddRow(string.Empty, Hint("Use {n:000} for a zero-padded counter, e.g. \"{n:000}_\" -> \"007_\"."));
                AddRow("Start", Number(_step.Start, v => _step!.Start = v));
                AddRow("Step", Number(_step.Step, v => _step!.Step = v));
                AddRow("Position", Combo(new[] { "prefix", "suffix" },
                    _step.Position == Position.Suffix ? "suffix" : "prefix",
                    v => _step!.Position = v == "suffix" ? Position.Suffix : Position.Prefix));
                break;

            case StepOp.Case:
                AddRow("Mode", Combo(new[] { "upper", "lower", "title" }, _step.CaseMode.ToString().ToLowerInvariant(),
                    v => _step!.CaseMode = v switch
                    {
                        "upper" => CaseMode.Upper,
                        "title" => CaseMode.Title,
                        _ => CaseMode.Lower,
                    }));
                break;

            case StepOp.Extension:
                var extMode = Combo(new[] { "lower", "upper", "set" }, _step.ExtensionMode.ToString().ToLowerInvariant());
                extMode.SelectedIndexChanged += (_, _) =>
                {
                    if (_suspend || _step is null) return;
                    _step.ExtensionMode = extMode.SelectedItem!.ToString() switch
                    {
                        "upper" => ExtensionMode.Upper,
                        "set" => ExtensionMode.Set,
                        _ => ExtensionMode.Lower,
                    };
                    Rebuild();
                    OnChanged();
                };
                AddRow("Mode", extMode);
                if (_step.ExtensionMode == ExtensionMode.Set)
                {
                    AddRow("Value", Text(_step.Value, v => _step!.Value = v));
                    AddRow(string.Empty, Hint("No leading dot. A file without an extension gains one."));
                }
                AddRow(string.Empty, Hint("Extension steps always act on the extension, whatever the scope is."));
                break;
        }

        _table.ResumeLayout();
        _suspend = false;
    }

    private void AddRow(string label, Control control)
    {
        _table.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        _table.Controls.Add(new Label
        {
            Text = label,
            AutoSize = true,
            Anchor = AnchorStyles.Left,
            Margin = new Padding(3, 7, 3, 3),
        }, 0, _table.RowCount);
        control.Margin = new Padding(3, 4, 3, 3);
        _table.Controls.Add(control, 1, _table.RowCount);
        _table.RowCount++;
    }

    private static Label Hint(string text) => new()
    {
        Text = text,
        AutoSize = true,
        MaximumSize = new Size(360, 0),
        ForeColor = SystemColors.GrayText,
    };

    private TextBox Text(string value, Action<string> setter)
    {
        var box = new TextBox { Text = value, Width = 320, Anchor = AnchorStyles.Left | AnchorStyles.Right };
        box.TextChanged += (_, _) =>
        {
            if (_suspend) return;
            setter(box.Text);
            OnChanged();
        };
        return box;
    }

    private CheckBox Check(string text, bool value, Action<bool> setter)
    {
        var box = new CheckBox { Text = text, Checked = value, AutoSize = true };
        box.CheckedChanged += (_, _) =>
        {
            if (_suspend) return;
            setter(box.Checked);
            OnChanged();
        };
        return box;
    }

    private NumericUpDown Number(int value, Action<int> setter)
    {
        var box = new NumericUpDown { Minimum = -100000, Maximum = 100000, Value = value, Width = 100 };
        box.ValueChanged += (_, _) =>
        {
            if (_suspend) return;
            setter((int)box.Value);
            OnChanged();
        };
        return box;
    }

    private ComboBox Combo(string[] values, string selected, Action<string>? setter = null)
    {
        var box = new ComboBox { DropDownStyle = ComboBoxStyle.DropDownList, Width = 180 };
        box.Items.AddRange(values);
        box.SelectedItem = values.Contains(selected) ? selected : values[0];
        if (setter is not null)
        {
            box.SelectedIndexChanged += (_, _) =>
            {
                if (_suspend) return;
                setter(box.SelectedItem!.ToString()!);
                OnChanged();
            };
        }
        return box;
    }

    private void OnChanged() => Changed?.Invoke(this, EventArgs.Empty);
}

