using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

internal sealed class MainForm : Form
{
    private readonly RuleSet _rules = new();
    private readonly Stack<RenameBatch> _undoStack = new();
    private List<FileEntry> _entries = new();
    private RenamePlan _plan = new();
    private string _folder = string.Empty;

    private readonly TextBox _folderBox = new();
    private readonly ComboBox _applyToBox = new();
    private readonly ComboBox _sortBox = new();
    private readonly ListBox _stepList = new();
    private readonly StepEditor _stepEditor = new();
    private readonly DataGridView _grid = new();
    private readonly ToolStripStatusLabel _summaryLabel = new();
    private readonly ToolStripStatusLabel _hintLabel = new();
    private readonly Button _applyButton = new();
    private readonly Button _undoButton = new();
    private readonly CheckBox _hideUnchanged = new();

    private bool _loading;

    public MainForm(string? startFolder)
    {
        Text = "Batch Rename Studio";
        MinimumSize = new Size(980, 620);
        Size = new Size(1180, 720);
        StartPosition = FormStartPosition.CenterScreen;

        BuildLayout();
        SyncRuleControls();
        RefreshStepList();

        if (!string.IsNullOrWhiteSpace(startFolder) && Directory.Exists(startFolder))
            LoadFolder(startFolder!);
        else
            UpdatePreview();
    }

    // ---------------------------------------------------------------- layout

    private void BuildLayout()
    {
        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            SplitterDistance = 430,
            FixedPanel = FixedPanel.Panel1,
        };
        Controls.Add(split); // Fill first: docked edges added later stay outside it.

        Controls.Add(BuildTopBar());
        Controls.Add(BuildBottomBar());
        Controls.Add(BuildStatusBar());

        split.Panel1.Controls.Add(BuildRulesPane());
        split.Panel2.Controls.Add(BuildPreviewPane());
    }

    private Control BuildTopBar()
    {
        var panel = new Panel { Dock = DockStyle.Top, Height = 78, Padding = new Padding(10, 8, 10, 4) };

        var folderLabel = new Label { Text = "Folder", AutoSize = true, Location = new Point(10, 12) };
        _folderBox.SetBounds(64, 8, 640, 24);
        _folderBox.Anchor = AnchorStyles.Left | AnchorStyles.Top | AnchorStyles.Right;
        _folderBox.ReadOnly = true;
        _folderBox.PlaceholderText = "Choose a folder to preview...";

        var browse = new Button { Text = "Browse...", Bounds = new Rectangle(712, 7, 90, 26), Anchor = AnchorStyles.Top | AnchorStyles.Right };
        browse.Click += (_, _) => BrowseFolder();

        var reload = new Button { Text = "Reload", Bounds = new Rectangle(808, 7, 80, 26), Anchor = AnchorStyles.Top | AnchorStyles.Right };
        reload.Click += (_, _) => { if (_folder.Length > 0) LoadFolder(_folder); };

        var scopeLabel = new Label { Text = "Apply to", AutoSize = true, Location = new Point(10, 46) };
        _applyToBox.DropDownStyle = ComboBoxStyle.DropDownList;
        _applyToBox.Items.AddRange(new object[] { "name", "nameAndExtension" });
        _applyToBox.SetBounds(64, 42, 160, 24);
        _applyToBox.SelectedIndexChanged += (_, _) =>
        {
            if (_loading) return;
            _rules.ApplyTo = _applyToBox.SelectedIndex == 1 ? ApplyTo.NameAndExtension : ApplyTo.Name;
            UpdatePreview();
        };

        var sortLabel = new Label { Text = "Order", AutoSize = true, Location = new Point(240, 46) };
        _sortBox.DropDownStyle = ComboBoxStyle.DropDownList;
        _sortBox.Items.AddRange(new object[] { "name", "created", "modified" });
        _sortBox.SetBounds(290, 42, 140, 24);
        _sortBox.SelectedIndexChanged += (_, _) =>
        {
            if (_loading) return;
            _rules.Sort = _sortBox.SelectedIndex switch { 1 => SortMode.Created, 2 => SortMode.Modified, _ => SortMode.Name };
            UpdatePreview();
        };

        var loadRules = new Button { Text = "Load rules...", Bounds = new Rectangle(450, 41, 110, 26) };
        loadRules.Click += (_, _) => LoadRules();

        var saveRules = new Button { Text = "Save rules...", Bounds = new Rectangle(566, 41, 110, 26) };
        saveRules.Click += (_, _) => SaveRules();

        panel.Controls.AddRange(new Control[]
        {
            folderLabel, _folderBox, browse, reload,
            scopeLabel, _applyToBox, sortLabel, _sortBox, loadRules, saveRules,
        });
        return panel;
    }

    private Control BuildRulesPane()
    {
        var host = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Horizontal,
            SplitterDistance = 230,
        };

        var listHost = new Panel { Dock = DockStyle.Fill };
        _stepList.Dock = DockStyle.Fill;
        _stepList.IntegralHeight = false;
        _stepList.Font = new Font(FontFamily.GenericMonospace, 8.75f);
        _stepList.SelectedIndexChanged += (_, _) => _stepEditor.Bind(SelectedStep());

        var tools = new ToolStrip { Dock = DockStyle.Top, GripStyle = ToolStripGripStyle.Hidden };

        var addButton = new ToolStripDropDownButton("Add step");
        foreach (var op in new[] { StepOp.Replace, StepOp.Insert, StepOp.Remove, StepOp.Sequence, StepOp.Case, StepOp.Extension })
        {
            var captured = op;
            addButton.DropDownItems.Add(op.ToString().ToLowerInvariant(), null, (_, _) => AddStep(captured));
        }

        var removeButton = new ToolStripButton("Remove") { DisplayStyle = ToolStripItemDisplayStyle.Text };
        removeButton.Click += (_, _) => RemoveStep();

        var upButton = new ToolStripButton("Move up") { DisplayStyle = ToolStripItemDisplayStyle.Text };
        upButton.Click += (_, _) => MoveStep(-1);

        var downButton = new ToolStripButton("Move down") { DisplayStyle = ToolStripItemDisplayStyle.Text };
        downButton.Click += (_, _) => MoveStep(1);

        var dupButton = new ToolStripButton("Duplicate") { DisplayStyle = ToolStripItemDisplayStyle.Text };
        dupButton.Click += (_, _) => DuplicateStep();

        tools.Items.AddRange(new ToolStripItem[]
        {
            addButton, removeButton, new ToolStripSeparator(), upButton, downButton, dupButton,
        });

        listHost.Controls.Add(_stepList);
        listHost.Controls.Add(tools);
        listHost.Controls.Add(new Label
        {
            Dock = DockStyle.Top,
            Text = "  Rule steps run top to bottom",
            Height = 22,
            TextAlign = ContentAlignment.MiddleLeft,
            ForeColor = SystemColors.GrayText,
        });

        _stepEditor.Dock = DockStyle.Fill;
        _stepEditor.Changed += (_, _) =>
        {
            RefreshStepList(keepSelection: true);
            UpdatePreview();
        };

        host.Panel1.Controls.Add(listHost);
        host.Panel2.Controls.Add(_stepEditor);
        return host;
    }

    private Control BuildPreviewPane()
    {
        var host = new Panel { Dock = DockStyle.Fill };

        _grid.Dock = DockStyle.Fill;
        _grid.ReadOnly = true;
        _grid.AllowUserToAddRows = false;
        _grid.AllowUserToDeleteRows = false;
        _grid.AllowUserToResizeRows = false;
        _grid.RowHeadersVisible = false;
        _grid.SelectionMode = DataGridViewSelectionMode.FullRowSelect;
        _grid.AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill;
        _grid.EnableHeadersVisualStyles = false;
        _grid.Columns.Add(NewColumn("#", 40, DataGridViewAutoSizeColumnMode.None));
        _grid.Columns.Add(NewColumn("Original", 200, DataGridViewAutoSizeColumnMode.Fill));
        _grid.Columns.Add(NewColumn("Proposed", 200, DataGridViewAutoSizeColumnMode.Fill));
        _grid.Columns.Add(NewColumn("Status", 90, DataGridViewAutoSizeColumnMode.None));
        _grid.Columns.Add(NewColumn("Reason", 200, DataGridViewAutoSizeColumnMode.Fill));

        var header = new Panel { Dock = DockStyle.Top, Height = 26 };
        _hideUnchanged.Text = "Hide unchanged";
        _hideUnchanged.AutoSize = true;
        _hideUnchanged.Location = new Point(6, 4);
        _hideUnchanged.CheckedChanged += (_, _) => RenderPlan();
        header.Controls.Add(_hideUnchanged);

        host.Controls.Add(_grid);
        host.Controls.Add(header);
        return host;
    }

    private static DataGridViewTextBoxColumn NewColumn(string name, int width, DataGridViewAutoSizeColumnMode mode) => new()
    {
        HeaderText = name,
        Width = width,
        AutoSizeMode = mode,
        SortMode = DataGridViewColumnSortMode.NotSortable,
    };

    private Control BuildBottomBar()
    {
        var panel = new Panel { Dock = DockStyle.Bottom, Height = 46, Padding = new Padding(10, 8, 10, 8) };

        _applyButton.Text = "Apply rename";
        _applyButton.SetBounds(10, 8, 130, 30);
        _applyButton.Click += (_, _) => ApplyRename();

        _undoButton.Text = "Undo last";
        _undoButton.SetBounds(150, 8, 110, 30);
        _undoButton.Enabled = false;
        _undoButton.Click += (_, _) => UndoLast();

        panel.Controls.AddRange(new Control[] { _applyButton, _undoButton });
        return panel;
    }

    private Control BuildStatusBar()
    {
        var status = new StatusStrip { Dock = DockStyle.Bottom };
        _summaryLabel.Text = "No folder loaded";
        _hintLabel.Spring = true;
        _hintLabel.TextAlign = ContentAlignment.MiddleRight;
        status.Items.Add(_summaryLabel);
        status.Items.Add(_hintLabel);
        return status;
    }

    // ---------------------------------------------------------------- rules

    private RuleStep? SelectedStep() =>
        _stepList.SelectedIndex >= 0 && _stepList.SelectedIndex < _rules.Steps.Count
            ? _rules.Steps[_stepList.SelectedIndex]
            : null;

    private void SyncRuleControls()
    {
        _loading = true;
        _applyToBox.SelectedIndex = _rules.ApplyTo == ApplyTo.NameAndExtension ? 1 : 0;
        _sortBox.SelectedIndex = _rules.Sort switch { SortMode.Created => 1, SortMode.Modified => 2, _ => 0 };
        _loading = false;
    }

    private void RefreshStepList(bool keepSelection = false)
    {
        var selected = _stepList.SelectedIndex;
        _stepList.BeginUpdate();
        _stepList.Items.Clear();
        for (var i = 0; i < _rules.Steps.Count; i++)
            _stepList.Items.Add($"{i + 1,2}. {_rules.Steps[i].Describe()}");
        _stepList.EndUpdate();

        if (_rules.Steps.Count == 0)
        {
            _stepEditor.Bind(null);
            return;
        }
        var target = keepSelection ? selected : Math.Min(selected < 0 ? 0 : selected, _rules.Steps.Count - 1);
        _stepList.SelectedIndex = Math.Clamp(target, 0, _rules.Steps.Count - 1);
    }

    private void AddStep(StepOp op)
    {
        var step = new RuleStep { Op = op };
        if (op == StepOp.Sequence) step.Pattern = "{n:000}_";
        _rules.Steps.Add(step);
        RefreshStepList();
        _stepList.SelectedIndex = _rules.Steps.Count - 1;
        _stepEditor.Bind(step);
        UpdatePreview();
    }

    private void RemoveStep()
    {
        var i = _stepList.SelectedIndex;
        if (i < 0 || i >= _rules.Steps.Count) return;
        _rules.Steps.RemoveAt(i);
        RefreshStepList();
        if (_rules.Steps.Count > 0) _stepList.SelectedIndex = Math.Min(i, _rules.Steps.Count - 1);
        _stepEditor.Bind(SelectedStep());
        UpdatePreview();
    }

    private void DuplicateStep()
    {
        var i = _stepList.SelectedIndex;
        if (i < 0 || i >= _rules.Steps.Count) return;
        _rules.Steps.Insert(i + 1, _rules.Steps[i].Clone());
        RefreshStepList();
        _stepList.SelectedIndex = i + 1;
        _stepEditor.Bind(SelectedStep());
        UpdatePreview();
    }

    private void MoveStep(int delta)
    {
        var i = _stepList.SelectedIndex;
        var j = i + delta;
        if (i < 0 || j < 0 || j >= _rules.Steps.Count) return;
        (_rules.Steps[i], _rules.Steps[j]) = (_rules.Steps[j], _rules.Steps[i]);
        RefreshStepList();
        _stepList.SelectedIndex = j;
        _stepEditor.Bind(SelectedStep());
        UpdatePreview();
    }

    private void LoadRules()
    {
        using var dialog = new OpenFileDialog { Filter = "Rule sets (*.json)|*.json|All files (*.*)|*.*" };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;
        try
        {
            var loaded = RuleIo.Load(dialog.FileName);
            _rules.ApplyTo = loaded.ApplyTo;
            _rules.Sort = loaded.Sort;
            _rules.Steps.Clear();
            _rules.Steps.AddRange(loaded.Steps);
            SyncRuleControls();
            RefreshStepList();
            _stepEditor.Bind(SelectedStep());
            UpdatePreview();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Could not load rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void SaveRules()
    {
        using var dialog = new SaveFileDialog { Filter = "Rule sets (*.json)|*.json", FileName = "rules.json" };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;
        try
        {
            RuleIo.Save(_rules, dialog.FileName);
            _hintLabel.Text = $"Saved {Path.GetFileName(dialog.FileName)}";
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Could not save rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    // ---------------------------------------------------------------- files & preview

    private void BrowseFolder()
    {
        using var dialog = new FolderBrowserDialog { ShowNewFolderButton = false };
        if (_folder.Length > 0) dialog.SelectedPath = _folder;
        if (dialog.ShowDialog(this) != DialogResult.OK) return;
        LoadFolder(dialog.SelectedPath);
    }

    private void LoadFolder(string folder)
    {
        try
        {
            _entries = RenameEngine.Scan(folder);
            _folder = folder;
            _folderBox.Text = folder;
            _undoStack.Clear();
            _undoButton.Enabled = false;
            UpdatePreview();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Could not read folder", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void UpdatePreview()
    {
        _plan = RenameEngine.BuildPlan(_entries, _rules);
        RenderPlan();
    }

    private void RenderPlan()
    {
        _grid.SuspendLayout();
        _grid.Rows.Clear();

        for (var i = 0; i < _plan.Items.Count; i++)
        {
            var item = _plan.Items[i];
            if (_hideUnchanged.Checked && item.Status == PlanStatus.Unchanged) continue;

            var index = _grid.Rows.Add(i + 1, item.Original, item.Proposed, item.Status, item.Reason);
            var row = _grid.Rows[index];
            row.DefaultCellStyle.BackColor = item.Status switch
            {
                PlanStatus.Ok => Color.FromArgb(233, 247, 233),
                PlanStatus.Collision => Color.FromArgb(255, 234, 230),
                PlanStatus.Invalid => Color.FromArgb(255, 226, 226),
                _ => Color.White,
            };
            if (item.Status == PlanStatus.Unchanged) row.DefaultCellStyle.ForeColor = SystemColors.GrayText;
        }

        _grid.ResumeLayout();

        var s = _plan.Summary;
        _summaryLabel.Text = _folder.Length == 0
            ? "No folder loaded"
            : $"total {s.Total}   ok {s.Ok}   collision {s.Collision}   unchanged {s.Unchanged}   invalid {s.Invalid}";
        _applyButton.Enabled = s.Ok > 0;
        _applyButton.Text = s.Ok > 0 ? $"Apply rename ({s.Ok})" : "Apply rename";
    }

    // ---------------------------------------------------------------- apply & undo

    private void ApplyRename()
    {
        if (_folder.Length == 0) return;

        // Re-scan first: the folder may have changed since the preview was built.
        _entries = RenameEngine.Scan(_folder);
        UpdatePreview();

        var ok = _plan.Items.Where(i => i.Status == PlanStatus.Ok).ToList();
        if (ok.Count == 0)
        {
            MessageBox.Show(this, "Nothing to rename.", "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }

        var confirm = MessageBox.Show(this,
            $"Rename {ok.Count} file(s) in\n{_folder}?\n\nFiles marked collision, invalid or unchanged are skipped.",
            "Confirm rename", MessageBoxButtons.OKCancel, MessageBoxIcon.Question);
        if (confirm != DialogResult.OK) return;

        var batch = RenameExecutor.Apply(_folder, ok, DateTime.UtcNow);
        if (batch.Records.Count > 0)
        {
            _undoStack.Push(batch);
            _undoButton.Enabled = true;
        }

        _entries = RenameEngine.Scan(_folder);
        UpdatePreview();

        _hintLabel.Text = $"Renamed {batch.Records.Count} file(s)";
        if (batch.Errors.Count > 0)
        {
            MessageBox.Show(this,
                $"Renamed {batch.Records.Count} file(s). {batch.Errors.Count} failed:\n\n" +
                string.Join("\n", batch.Errors.Take(15)),
                "Some files could not be renamed", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void UndoLast()
    {
        if (_undoStack.Count == 0) return;
        var batch = _undoStack.Pop();
        var errors = RenameExecutor.Undo(batch);

        _entries = RenameEngine.Scan(batch.Directory);
        if (!string.Equals(batch.Directory, _folder, StringComparison.OrdinalIgnoreCase))
        {
            _folder = batch.Directory;
            _folderBox.Text = _folder;
        }
        UpdatePreview();

        _undoButton.Enabled = _undoStack.Count > 0;
        _hintLabel.Text = $"Undid {batch.Records.Count} rename(s)";
        if (errors.Count > 0)
        {
            MessageBox.Show(this, string.Join("\n", errors.Take(15)), "Undo was incomplete",
                MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }
}

