1	using System.Text;
2	using System.Text.Encodings.Web;
3	using System.Text.Json;
4	using System.Text.RegularExpressions;
5	
6	namespace BatchRenameStudio.Core;
7	
8	/// <summary>
9	/// Reads and writes the <c>rules.json</c> format described in the tool contract.
10	/// Parsing is deliberately strict about op names and enum values (a typo there silently
11	/// changes the whole result) and lenient about missing optional fields.
12	/// </summary>
13	public static class RuleIo
14	{
15	    public static RuleSet Load(string path)
16	    {
17	        string text;
18	        try
19	        {
20	            text = File.ReadAllText(path);
21	        }
22	        catch (Exception ex)
23	        {
24	            throw new RuleException($"cannot read rules file '{path}': {ex.Message}");
25	        }
26	        return Parse(text);
27	    }
28	
29	    public static RuleSet Parse(string json)
30	    {
31	        JsonDocument doc;
32	        try
33	        {
34	            doc = JsonDocument.Parse(json, new JsonDocumentOptions
35	            {
36	                AllowTrailingCommas = true,
37	                CommentHandling = JsonCommentHandling.Skip,
38	            });
39	        }
40	        catch (JsonException ex)
41	        {
42	            throw new RuleException($"rules file is not valid JSON: {ex.Message}");
43	        }
44	
45	        using (doc)
46	        {
47	            var root = doc.RootElement;
48	            if (root.ValueKind != JsonValueKind.Object)
49	                throw new RuleException("rules file must contain a JSON object at the root.");
50	
51	            var set = new RuleSet
52	            {
53	                ApplyTo = ParseEnum(GetString(root, "applyTo") ?? "name", "applyTo", new Dictionary<string, ApplyTo>
54	                {
55	                    ["name"] = ApplyTo.Name,
56	                    ["nameandextension"] = ApplyTo.NameAndExtension,
57	                }),
58	                Sort = ParseEnum(GetString(root, "sort") ?? "name", "sort", new Dictionary<string, SortMode>
59	                {
60	                    ["name"] = SortMode.Name,
61	                    ["created"] = SortMode.Created,
62	                    ["modified"] = SortMode.Modified,
63	                }),
64	            };
65	
66	            if (root.TryGetProperty("steps", out var steps))
67	            {
68	                if (steps.ValueKind != JsonValueKind.Array)
69	                    throw new RuleException("'steps' must be an array.");
70	                var i = 0;
71	                foreach (var e in steps.EnumerateArray())
72	                {
73	                    set.Steps.Add(ParseStep(e, i));
74	                    i++;
75	                }
76	            }
77	
78	            return set;
79	        }
80	    }
81	
82	    private static RuleStep ParseStep(JsonElement e, int index)
83	    {
84	        if (e.ValueKind != JsonValueKind.Object)
85	            throw new RuleException($"steps[{index}] must be an object.");
86	
87	        var opText = GetString(e, "op") ?? throw new RuleException($"steps[{index}] is missing 'op'.");
88	        var step = new RuleStep
89	        {
90	            Op = ParseEnum(opText, $"steps[{index}].op", new Dictionary<string, StepOp>
91	            {
92	                ["replace"] = StepOp.Replace,
93	                ["insert"] = StepOp.Insert,
94	                ["remove"] = StepOp.Remove,
95	                ["sequence"] = StepOp.Sequence,
96	                ["case"] = StepOp.Case,
97	                ["extension"] = StepOp.Extension,
98	            }),
99	        };
100	
101	        switch (step.Op)
102	        {
103	            case StepOp.Replace:
104	                step.Find = GetString(e, "find") ?? string.Empty;
105	                step.ReplaceWith = GetString(e, "replaceWith") ?? string.Empty;
106	                step.Regex = GetBool(e, "regex", false);
107	                step.IgnoreCase = GetBool(e, "ignoreCase", false);
108	                if (step.Regex)
109	                {
110	                    try
111	                    {
112	                        _ = new Regex(step.Find, step.IgnoreCase ? RegexOptions.IgnoreCase : RegexOptions.None);
113	                    }
114	                    catch (ArgumentException ex)
115	                    {
116	                        throw new RuleException($"steps[{index}] has an invalid regex: {ex.Message}");
117	                    }
118	                }
119	                break;
120	
121	            case StepOp.Insert:
122	                step.Text = GetString(e, "text") ?? string.Empty;
123	                step.Position = ParsePosition(GetString(e, "position") ?? "prefix", $"steps[{index}].position", allowIndex: true);
124	                step.Index = GetInt(e, "index", 0);
125	                break;
126	
127	            case StepOp.Remove:
128	                step.From = GetInt(e, "from", 0);
129	                step.Count = GetInt(e, "count", 0);
130	                break;
131	
132	            case StepOp.Sequence:
133	                step.Pattern = GetString(e, "pattern") ?? "{n:000}";
134	                step.Start = GetInt(e, "start", 1);
135	                step.Step = GetInt(e, "step", 1);
136	                step.Position = ParsePosition(GetString(e, "position") ?? "prefix", $"steps[{index}].position", allowIndex: false);
137	                break;
