using System.Runtime.InteropServices;
using BatchRenameStudio.Cli;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        // Headless contract takes precedence over the GUI.
        if (args.Any(a => string.Equals(a, "--plan", StringComparison.OrdinalIgnoreCase)))
            return PlanCommand.Run(args);

        DetachOwnConsole();

        ApplicationConfiguration.Initialize();

        // An optional folder path may be passed to open the GUI on that folder.
        var startFolder = args.FirstOrDefault(a => !a.StartsWith("-", StringComparison.Ordinal));
        Application.Run(new MainForm(startFolder));
        return 0;
    }

    // The binary is a console-subsystem executable so that `--plan` behaves like a normal
    // command line tool (the shell waits for it, stdout redirection just works). In GUI mode
    // that console is unwanted, so it is dropped -- but only when it belongs to us. Launched
    // from an existing cmd/PowerShell window the console is shared, and closing it would take
    // the user's shell with it.
    private const int SwHide = 0;

    [DllImport("kernel32.dll")]
    private static extern uint GetConsoleProcessList(uint[] processList, uint count);

    [DllImport("kernel32.dll")]
    private static extern IntPtr GetConsoleWindow();

    [DllImport("kernel32.dll")]
    private static extern bool FreeConsole();

    [DllImport("user32.dll")]
    private static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

    private static void DetachOwnConsole()
    {
        try
        {
            var buffer = new uint[4];
            var attached = GetConsoleProcessList(buffer, (uint)buffer.Length);
            if (attached != 1) return; // shared with a parent shell: leave it alone

            var window = GetConsoleWindow();
            if (window != IntPtr.Zero) ShowWindow(window, SwHide);
            FreeConsole();
        }
        catch
        {
            // Running without a console at all is fine.
        }
    }
}

