using BatchRenameStudio.Core;

var root = Path.Combine(Path.GetTempPath(), "brs-exectest");
if (Directory.Exists(root)) Directory.Delete(root, true);
Directory.CreateDirectory(root);

// A swap: a.txt -> b.txt and b.txt -> a.txt. Single-phase renaming cannot do this.
File.WriteAllText(Path.Combine(root, "a.txt"), "A");
File.WriteAllText(Path.Combine(root, "b.txt"), "B");

var rules = new RuleSet { ApplyTo = ApplyTo.Name, Sort = SortMode.Name };
rules.Steps.Add(new RuleStep { Op = StepOp.Replace, Find = "a", ReplaceWith = "Z" });
rules.Steps.Add(new RuleStep { Op = StepOp.Replace, Find = "b", ReplaceWith = "a" });
rules.Steps.Add(new RuleStep { Op = StepOp.Replace, Find = "Z", ReplaceWith = "b" });

var plan = RenameEngine.BuildPlan(root, rules);
Console.WriteLine("plan: " + string.Join(", ", plan.Items.Select(i => $"{i.Original}->{i.Proposed}[{i.Status}]")));

var batch = RenameExecutor.Apply(root, plan.Items, DateTime.UtcNow);
Console.WriteLine($"applied {batch.Records.Count}, errors {batch.Errors.Count}");
Console.WriteLine("after apply:   " + string.Join(", ",
    Directory.GetFiles(root).OrderBy(f => f).Select(f => $"{Path.GetFileName(f)}={File.ReadAllText(f)}")));

var errors = RenameExecutor.Undo(batch);
Console.WriteLine($"undo errors {errors.Count}");
Console.WriteLine("after undo:    " + string.Join(", ",
    Directory.GetFiles(root).OrderBy(f => f).Select(f => $"{Path.GetFileName(f)}={File.ReadAllText(f)}")));

var swapped = File.Exists(Path.Combine(root, "a.txt")) && File.ReadAllText(Path.Combine(root, "a.txt")) == "A"
           && File.Exists(Path.Combine(root, "b.txt")) && File.ReadAllText(Path.Combine(root, "b.txt")) == "B";
Console.WriteLine(swapped ? "ROUNDTRIP OK" : "ROUNDTRIP FAILED");

Directory.Delete(root, true);

